    "team_spike_cold_0": "Monety w moich kolcach pokryły się szronem. Liczenie jest teraz zimne i brzęczące.",
    "team_spike_cold_1": "Zoya przywiązała mi szalik do jednego kolca. Reszta musi sobie radzić.",
    "team_spike_cold_2": "Zimą ciepła zostaje tylko ta część kasy, na której leży moja łapa.",
    "team_bodya_cold_0": "Deski śpiewają na mrozie. Nikt nie prosił, a brzmi jak orkiestra.",
    "team_bodya_cold_1": "Mikhas przyniósł skrzynie, które pachną śniegiem. Postawię je przy piecu, niech się obudzą.",
    "team_bodya_cold_2": "Marzę o warsztacie z kominkiem. Plany są, na serwetce po herbacie.",
    "team_zoya_cold_0": "Szron rysuje wzory na witrynie. To konkurencja i do tego ładna.",
    "team_zoya_cold_1": "Uszy mi zmarzły, ale humor mam różowy. Przydałaby się czapka, też różowa.",
    "team_zoya_cold_2": "Zhuzha mówi, że szalik to dodatek. Ja mówię, że to ratunek, tylko ładny.",
    "team_tonya_cold_0": "Jestem wolna, a zimno jest jeszcze wolniejsze. Wreszcie ktoś, z kim mogę się ścigać.",
    "team_tonya_cold_1": "W skorupie jest ciepło. Inni mają kieszenie; niech mi zazdroszczą.",
    "team_tonya_cold_2": "Ten sklep widział sto czterdzieści zim. Ta wydaje się zimniejsza. Albo ja starsza.",
    "team_mikhas_cold_0": "Jestem niedźwiedziem, nie jest mi zimno. Chcę tylko spać do wiosny.",
    "team_mikhas_cold_1": "Skrzynie zamarzły w wieżę. Spike mówi „architektura”. Ja mówię „problem”.",
    "team_mikhas_cold_2": "Marzę o gawrze i misce miodu. Tylko na zimę, tylko na razie.",
    "team_sonia_cold_0": "Atrament zamarza, cyfry wychodzą poszarpane. Bilans się zgadza, z iskrą.",
    "team_sonia_cold_1": "Leo mówi „zimno to wyzwanie”. Ja mówię „zimno to powód do koca”.",
    "team_sonia_cold_2": "Nastroszyłam pióra i urosłam trzykrotnie. Księgowość mnie nie poznaje.",
    "team_kria_cold_0": "Mop jest w objęciach lodu. Ratuję go, jak mogę: kaloszami i szczerym sercem.",
    "team_kria_cold_1": "Zhuzha mówi, że kalosze to nie buty zimowe. Dla mnie są letnie, zimowe i odświętne.",
    "team_kria_cold_2": "Myję podłogę, a ona od razu zamarza. Wieczny połysk bez wysiłku.",
    "team_zhuzha_cold_0": "Sześć warstw ubrań to nie przesada, to strategia.",
    "team_zhuzha_cold_1": "Moje łapki nigdy nie były tak daleko od kałuży. Tęsknię za nią.",
    "team_zhuzha_cold_2": "Kria nie rozumie, po co mi dwa szaliki. To oczywiste: jeden dla stylu, drugi dla duszy.",
    "team_leo_cold_0": "Zimno to świetna okazja, żeby przenieść zebranie na lato.",
    "team_leo_cold_1": "Efektywność spadła do zera stopni Celsjusza. To też wskaźnik, nawiasem mówiąc.",
    "team_leo_cold_2": "Ubierajcie się cieplej, zespole. To nie rada, to kluczowy wskaźnik efektywności.",
    "team_pao_cold_0": "Bambus zamarzł. To nie trend, to katastrofa, a ja już piszę reklamę.",
    "team_pao_cold_1": "Nowe hasło: „Kup szalik, dostaniesz ciepło”. Zoya już chce prowizji.",
    "team_pao_cold_2": "Marzę o mandarynkach i kocu. I o tym, żeby ktoś inny zapłacił za koc.",
    "team_murzyk_cold_0": "Łapy przymarzły mi do klawiatury. Dobra, piszę dwiema, reszta poczeka.",
    "team_murzyk_cold_1": "Kable zimą są kruche jak moje nerwy. Lepiej nie dotykać ani jednych, ani drugich.",
    "team_murzyk_cold_2": "Zimno? Włącz grzejnik. Albo mnie: robię się gorący, gdy zbliża się wydanie.",
    "team_toma_cold_0": "Pamiętam, kiedy było ciepło. To było w lipcu. Kiedyś.",
    "team_toma_cold_1": "Trąba zamarzła mi w lizak. Nie próbuj, ja już próbowałem.",
    "team_toma_cold_2": "Dzięki temu, kto mnie przykrył kocem. Nie zapomnę. Ja niczego nie zapominam.",
    "team_shnyr_cold_0": "Nie marznę. Po prostu pożyczyłem czapkę. Jej właściciel już jej nie potrzebuje.",
    "team_shnyr_cold_1": "Łapy mi marzną, a w śmietniku zimą jest cieplej. Fakt, nie sugestia.",
    "team_shnyr_cold_2": "Spike pilnuje kasy, ja pilnuję szalika. Był niczyj. Teraz jest mój.",
    "capy_cold_0": "Śnieg na dachach, a we mnie tęsknota za latem i gorącą kąpielą.",
    "capy_cold_1": "Zimno, ale w sklepie huczy praca. Ciepłe słowo też grzeje.",
    "capy_cold_2": "Kapibary zimą też marzą. Ja o gorących źródłach i ciszy.",
    "epoch_say_0_0": "Pachnie woskiem i świeżym chlebem. Przytulnie.",
    "epoch_say_0_1": "Ktoś znów maluje na ścianie. Nazywają to sztuką.",
    "epoch_say_0_2": "Cech kupców zatwierdził nasze ceny. A przynajmniej milczy.",
    "epoch_say_0_3": "Tu wszystko pisze się gęsim piórem. Paragony wciąż pachną atramentem.",
    "epoch_say_0_4": "Jeszcze jeden gobelin i byłby prawdziwy pałac.",
    "epoch_say_0_5": "Ktoś gra na lutni pod oknem. Fałszuje, ale z uczuciem.",
    "epoch_say_1_0": "Radio gra i trzeszczy jednocześnie. To jest retro.",
    "epoch_say_1_1": "Znów sterowiec nad dachami. Pewnie wiezie zniżki.",
    "epoch_say_1_2": "Koktajl mleczny i dzień uratowany.",
    "epoch_say_1_3": "Film za grosz? Poproszę dwa bilety.",
    "epoch_say_1_4": "Przewijam taśmę ołówkiem. Dziadek też tak robił.",
    "epoch_say_1_5": "Pastelowe kolory to najlepsze kolory. Nie kłóć się.",
    "epoch_say_2_0": "Kula dyskotekowa znów mruga. Czy ktoś tańczy bez muzyki?",
    "epoch_say_2_1": "Buty na platformie i wyższe ceny. Jest w tym prawidłowość.",
    "epoch_say_2_2": "Rytm jest tak mocny, że lady prawie tańczą.",
    "epoch_say_2_3": "Brokat to nie brud. To styl. Kria wie.",
    "epoch_say_2_4": "Disco nie umarło, tylko stoi przy kasie.",
    "epoch_say_2_5": "Raz, dwa, trzy... zniżka!",
    "epoch_say_3_0": "Jeszcze jedna moneta i nowy poziom. Wiem, co mówię.",
    "epoch_say_3_1": "Automaty mrugają. Moje serce też. W rytmie.",
    "epoch_say_3_2": "Nowy rekord na tablicy? Nie ja. Shnyr. Znowu.",
    "epoch_say_3_3": "Wszyscy tu mają trzy życia. Ktoś już zużył drugie.",
    "epoch_say_3_4": "Piksel to mała cegiełka szczęścia.",
    "epoch_say_3_5": "Słyszę ping i biegnę. Nawet gdy to nie do mnie.",
    "epoch_say_4_0": "Jest zasięg, ale na nic. Klasyka.",
    "epoch_say_4_1": "Ta karta czeka od pięciu lat, aż ją zamknę.",
    "epoch_say_4_2": "Dron przeleciał mi koło ucha. Przywitał się. Podskoczyłam.",
    "epoch_say_4_3": "Ktoś znów wrzucił zdjęcie jedzenia. Moje ciastko, nawiasem mówiąc.",
    "epoch_say_4_4": "Hasło „1234” to nie hasło, to prośba.",
    "epoch_say_4_5": "Wi-Fi łapie wszędzie oprócz mojego humoru.",
    "epoch_say_5_0": "Wiatrak się kręci, lampa świeci. Cicho, czysto, miło.",
    "epoch_say_5_1": "Pszczoła bzyczy mi koło ucha. To nie atak, to rozmowa.",
    "epoch_say_5_2": "Na dachu coś rośnie. Nikt nie pamięta, kto to posadził.",
    "epoch_say_5_3": "Herbata miętowa z własnego balkonu. To jest luksus.",
    "epoch_say_5_4": "Słońce grzeje za darmo. Dziwne, że nikt wcześniej na to nie wpadł.",
    "epoch_say_5_5": "Rowery tu dzwonią, a nie ryczą. Uwielbiam to.",
    "epoch_say_6_0": "Gwiazdy są dziś blisko. Prawie można ich dotknąć.",
    "epoch_say_6_1": "Skafander grzeje, okno chłodzi. Równowaga.",
    "epoch_say_6_2": "Wszystko tu jest trochę lżejsze. Nawet ceny.",
    "epoch_say_6_3": "Jak podskoczysz, zawisasz na sekundę. Nie sprawdzałam. Wielokrotnie.",
    "epoch_say_6_4": "Rakieta ryczy, ale już nas nie przeraża. Przyzwyczailiśmy się.",
    "epoch_say_6_5": "Ze stacji widać całe miasto. Jest małe i świeci.",
    "epoch_say_7_0": "Szyld mruga. Chyba przypomina mi, że nie jadłam.",
    "epoch_say_7_1": "Miasto nie śpi. Ja chyba też nie.",
    "epoch_say_7_2": "W tym cieniu lampa świeci jaśniej niż dzienne światło.",
    "epoch_say_7_3": "Róż i turkus to jedyna paleta, jakiej nam trzeba.",
    "epoch_say_7_4": "Nad głową przeleciała taksówka. Jedno spojrzenie i już się spóźniam.",
    "epoch_say_7_5": "Deszcz tu świeci. Więc mi nie przeszkadza.",
    "swEco": "Oszczędzanie energii",
    "setEcoNote": "Mniej cząsteczek; bez deszczu, pary i ptaków. Włącza się samo, gdy gra zwalnia.",
    "ecoAuto": "Gra działała wolno. Oszczędzanie energii włączone: mniej cząsteczek, bez deszczu i pary. Możesz je wyłączyć w Ustawieniach.",
    "setSaveNote2": "Gra trzyma drugą kopię zapisu i przywraca ją, gdy główny się zepsuje. Mimo to skopiuj kod raz w tygodniu i trzymaj w notatkach.",
    "exportNever": "Kod zapisu nie został jeszcze skopiowany.",
